def pig_latin(word):
    if word[0] in 'aeiou':
        return word + 'way'
    else:
        return word[1:] + word[0] + 'ay'

def main():
    word = input("Enter a word: ")
    print(pig_latin(word))

if __name__ == "__main__":
    main()
```

